import sys

def quicksort(arr, low, high):
    if low < high:
        pi = partition(arr, low, high)
        quicksort(arr, low, pi - 1)
        quicksort(arr, pi + 1, high)

def partition(arr, low, high):
    pivot = arr[high]
    i = low - 1
    for j in range(low, high):
        if arr[j] <= pivot:
            i += 1
            arr[i], arr[j] = arr[j], arr[i]
    arr[i + 1], arr[high] = arr[high], arr[i + 1]
    return i + 1

def binary_search(arr, x):
    low, high = 0, len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            return mid
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def find_median(sorted_arr):
    n = len(sorted_arr)
    if n % 2 == 1:
        return float(sorted_arr[n // 2])
    else:
        return (sorted_arr[n // 2 - 1] + sorted_arr[n // 2]) / 2.0

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    arr = list(map(int, data[1:n+1]))
    x = int(data[n+1])

    if n > 0:
        quicksort(arr, 0, n - 1)
        median = find_median(arr)
        idx = binary_search(arr, x)

        print("Sorted array:", " ".join(map(str, arr)) + " ")
        print("Median: {:.2f}".format(median))
        print("Binary Search Result:", idx)
    else:
        print("Sorted array: ")
        print("Median: 0.00")
        print("Binary Search Result:", -1)

if __name__ == "__main__":
    main()
